<script setup lang="ts">
import {ref,reactive,computed,watch,nextTick,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {IconArrowLeft,IconArrowUpRight,IconSearch,IconBook2,IconMaximize,IconX,IconArrowsExchange,IconCompass,IconLayoutGrid,IconGitCompare,IconChevronRight} from '@tabler/icons-vue'
import NeuralGraphCanvas from './NeuralGraphCanvas.vue'
import SealStudyChart from './SealStudyChart.vue'
const LandscapeScroll=defineAsyncComponent(()=>import('./LandscapeScroll.vue'))
const readingStart=ref<HTMLElement>()
function enterReading(){readingStart.value?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});readingStart.value?.focus({preventScroll:true})}
const universeRoot=ref<HTMLElement>()
async function openLandscape(){entranceShown.value=true;await nextTick();universeRoot.value?.scrollIntoView({behavior:'smooth',block:'start'})}
import registryJson from './museum-seals.json'
const registry=registryJson as MuseumRegistry
import {previewFor as matchedPreview,sealCharacters,relatedSeals,sealContext,comparedSeals,characterFrequency,isAsserted,sealDocuments,museumReadingData,museumRecordFor,isSeal} from './seal-domain'
import type {MuseumRegistry} from './seal-domain'
import type {GraphData,GraphNode} from './types'
import './seal-universe.css'
const props=defineProps<{data:GraphData|null;selected:string;selectedType:string;loading:boolean;error:string;initialAnchor?:string;directReading?:boolean}>()
const entranceShown=ref(!props.directReading)
const emit=defineEmits<{select:[id:string,type:'node'|'edge'];workbench:[id?:string,type?:'node'|'edge'];retry:[];anchor:[id:string];full:[]}>()
const anchor=ref(props.initialAnchor||''),query=ref(''),letter=ref(''),lens=ref<'read'|'related'>(innerWidth<600?'read':'related'),view=ref<'space'|'study'>('space'),compare=ref(''),expanded=ref(false),zoom=ref(1),mirror=ref(false),storyOpen=ref(false),failed=reactive(new Set<string>())
const modal=ref<HTMLElement>();let previousFocus:HTMLElement|null=null
const readingData=computed(()=>props.data?museumReadingData(props.data,registry):null)
const seals=computed(()=>readingData.value?.nodes.filter(n=>n.kind==='seal_object'&&n.matched!==false&&!!readingData.value)||[])
const current=computed(()=>seals.value.find(n=>n.id===anchor.value))
const preview=computed(()=>previewFor(current.value,registry))
const official=computed(()=>props.data?museumRecordFor(current.value,props.data,registry):undefined)
const catalog=computed(()=>seals.value.filter(n=>n.label.includes(query.value.trim())))
const characters=computed(()=>props.data?sealCharacters(readingData.value!,anchor.value):[])
const related=computed(()=>props.data?relatedSeals(readingData.value!,anchor.value,letter.value):[])
const activeRegistry=computed(()=>Object.fromEntries(Object.entries(registry).filter(([id])=>!failed.has(id))))
function previewFor(n:GraphNode|undefined,sourceRegistry=registry){return n&&!failed.has(n.id)?matchedPreview(n,sourceRegistry):undefined}
function markFailed(id?:string){if(id)failed.add(id)}
const context=computed(()=>props.data?sealContext(readingData.value!,anchor.value,lens.value,letter.value,activeRegistry.value,8):null)
const comparison=computed(()=>props.data&&compare.value?comparedSeals(readingData.value!,anchor.value,compare.value):null)
const compared=computed(()=>seals.value.find(n=>n.id===compare.value))
const selectedNode=computed(()=>props.data?.nodes.find(n=>n.id===props.selected))
const selectedEdge=computed(()=>props.data?.edges.find(e=>e.id===props.selected))
const edgeNames=computed(()=>{const edge=selectedEdge.value;if(!edge)return '';const name=(id:string)=>props.data?.nodes.find(n=>n.id===id)?.label||'';return name(edge.source)+' → '+name(edge.target)})
const anchorDocuments=computed(()=>props.data?sealDocuments(props.data,anchor.value):[])
const sourceDoc=computed(()=>anchorDocuments.value[0])
const claimDocuments=computed(()=>{const e=selectedEdge.value;if(!props.data||!e)return [];const ids=new Set(props.data.edges.filter(x=>isAsserted(x)&&x.source===e.source&&x.target===e.target&&x.predicate===e.predicate).map(x=>x.document_id));return props.data.documents.filter(d=>ids.has(d.id))})
const reviewSummary=computed(()=>selectedEdge.value?dataStatus(selectedEdge.value.status):'有网页出处，复核状态请查看证据')
function dataStatus(status:string){return props.data?.statuses[status]||'待核验'}
const provenance=computed(()=>selectedEdge.value?props.data?.documents.find(d=>d.id===selectedEdge.value!.document_id):sourceDoc.value)
const selectedChar=computed(()=>characters.value.find(r=>r.node.id===letter.value)?.node)
const fields=computed(()=>{const names=(p:string)=>[...new Set(props.data?.edges.filter(e=>isAsserted(e)&&e.source===anchor.value&&e.predicate===p).map(e=>props.data?.nodes.find(n=>n.id===e.target)?.label).filter(Boolean)||[])].join('、')||'暂无资料';return {script:official.value?.script||names('has_script'),kind:'馆藏实物记录',collection:official.value?.museum||'暂无馆藏凭证'}})
const stats=computed(()=>({characters:characterFrequency(readingData.value||{nodes:[],edges:[]} as unknown as GraphData).length,seals:seals.value.length}))
watch(()=>props.data,()=>{if(!seals.value.some(n=>n.id===anchor.value)){anchor.value=seals.value.find(n=>n.id===props.selected)?.id||seals.value[0]?.id||'';letter.value=''}if(letter.value&&(!props.data||!sealCharacters(readingData.value!,anchor.value).some(r=>r.node.id===letter.value)))letter.value='';if(compare.value&&!seals.value.some(n=>n.id===compare.value))compare.value=''}, {immediate:true})
watch(anchor,id=>emit('anchor',id),{immediate:true})
watch(()=>props.selected,id=>{const n=seals.value.find(n=>n.id===id);if(n&&anchor.value!==id){anchor.value=id;letter.value='';if(compare.value===id)compare.value=''}})
function selectSeal(n:GraphNode){anchor.value=n.id;letter.value='';if(compare.value===n.id)compare.value='';emit('select',n.id,'node')}
function chooseLetter(n:GraphNode){if(!characters.value.some(r=>r.node.id===n.id)){const first=props.data?.edges.find(e=>isAsserted(e)&&seals.value.some(s=>s.id===e.source)&&e.target===n.id&&e.predicate==='contains_character');const seal=seals.value.find(s=>s.id===first?.source);if(seal)selectSeal(seal)}letter.value=letter.value===n.id?'':n.id;lens.value='related';emit('select',n.id,'node')}
function inspect(id:string,type:'node'|'edge'){const node=props.data?.nodes.find(n=>n.id===id);if(type==='node'&&node&&isSeal(node))selectSeal(node);else if(type==='node'&&node?.kind==='character')chooseLetter(node);else emit('select',id,type)}
function clearLetter(){letter.value='';emit('select',anchor.value,'node')}
function addCompare(n:GraphNode){compare.value=compare.value===n.id?'':n.id}
function focusGuard(event:FocusEvent){if(expanded.value&&modal.value&&!modal.value.contains(event.target as Node))modal.value.querySelector<HTMLButtonElement>('button')?.focus()}
function removeDialogGuards(){document.removeEventListener('keydown',dialogKeys,true);document.removeEventListener('focusin',focusGuard,true)}
watch(expanded,async open=>{removeDialogGuards();if(open){previousFocus=document.activeElement as HTMLElement;zoom.value=1;mirror.value=false;await nextTick();if(!expanded.value||!modal.value)return;document.addEventListener('keydown',dialogKeys,true);document.addEventListener('focusin',focusGuard,true);modal.value.querySelector<HTMLButtonElement>('button')?.focus()}else if(previousFocus?.isConnected)previousFocus.focus()})
onBeforeUnmount(removeDialogGuards)
function dialogKeys(e:KeyboardEvent){if(e.key==='Escape')expanded.value=false;if(e.key!=='Tab')return;const all=Array.from(modal.value?.querySelectorAll<HTMLElement>('button,input,a[href]')||[]),first=all[0],last=all.at(-1);if(modal.value&&!modal.value.contains(document.activeElement)){e.preventDefault();first?.focus()}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
</script>

<template>
<main ref="universeRoot" class="seal-universe">
 <header class="seal-topbar"><RouterLink to="/culture" class="seal-back"><IconArrowLeft :size="16"/>文化溯源</RouterLink><div class="seal-wordmark">印脉重生 <span>SEAL REBORN</span></div><nav><button @click="storyOpen=!storyOpen" :aria-expanded="storyOpen"><IconBook2 :size="16"/>认识篆刻</button><button @click="emit('workbench',anchor||undefined,'node')"><IconLayoutGrid :size="16"/>资料工作台<IconArrowUpRight :size="13"/></button></nav></header>
 <button v-if="!entranceShown" class="seal-open-landscape" @click="openLandscape">画卷入境 · 赏千里江山 ↗</button>
 <LandscapeScroll v-if="entranceShown" :records="stats.seals" @enter="enterReading"/>
 <section ref="readingStart" class="seal-intro" tabindex="-1"><div><span class="seal-eyebrow">方寸之间 · 万象相连</span><h2>从一方印，走进知识宇宙。</h2><p>读它的文字，看它与其他馆藏印章的联系，循着证据找到出处。</p></div><div class="seal-corpus"><b>{{data?stats.seals:"—"}}<small>馆藏记录</small></b><b>{{data?stats.characters:"—"}}<small>释文汉字</small></b><span>官方记录可追溯<br>不代表完整馆藏</span></div></section>
 <aside v-if="storyOpen" class="seal-learning"><h2>字法 · 章法 · 刀法</h2><p>从文字结构读字法，从疏密留白看章法，从用刀认识线条表现。先细看一方印，再进入它的关联网络。</p><p>此处仅陈列有官方藏品页和可核对条目身份的馆藏记录。文字释读引用原站；不自行鉴定真伪，也不把共享文字当作历史传承。</p><a href="https://storymaps.arcgis.com/stories/08dbd922e8be475ba88f2f30566ecfe8" target="_blank" rel="noopener noreferrer">阅读《中国篆刻》原案例 ↗</a></aside>
 <p v-if="error" class="seal-error" role="alert">{{error}}<button @click="emit('retry')">重新读取</button></p>
 <p v-if="loading&&!data" class="seal-loading" role="status">正在打开印稿资料…</p>
 <div v-else-if="data&&current" class="seal-explorer">
  <aside class="seal-rail"><div class="seal-section-title"><span>01</span><h2>选一方印</h2><small>{{catalog.length}} / {{seals.length}}</small></div><label class="seal-search"><IconSearch :size="16"/><input v-model="query" aria-label="搜索印稿目录" placeholder="搜索印文，如：皇、宝"></label><div class="seal-catalog"><button v-for="n in catalog" :key="n.id" :class="{chosen:n.id===anchor}" :aria-pressed="n.id===anchor" :aria-label="'选读印稿：'+n.label" @click="selectSeal(n)"><img v-if="previewFor(n,registry)&&!failed.has(n.id)" :src="previewFor(n,registry)!.display_url" :alt="n.label+'官方馆藏图像'" loading="lazy" @error="failed.add(n.id)"><span v-else class="seal-no-preview">暂无预览</span><span><b>{{n.label}}</b><small>馆藏记录 · {{registry[n.id]?.museum}}</small></span><IconChevronRight :size="13"/></button><p v-if="!catalog.length" class="seal-catalog-empty">没有匹配的印稿，试试其他文字。</p></div><footer><i></i>图像与释文均可追溯原站</footer></aside>
  <section class="seal-stage"><header><div><span class="seal-eyebrow">02 · 沿印文探索</span><h2>{{current.label}}<small>{{fields.script}} · {{fields.kind}}</small></h2></div><div class="seal-view-tabs"><button :aria-pressed="view==='space'" @click="view='space'"><IconCompass :size="14"/>三维游观</button><button :aria-pressed="view==='study'" @click="view='study'"><IconBook2 :size="14"/>平面研读</button></div></header><div class="seal-lens"><button :aria-pressed="lens==='read'" @click="lens='read';letter=''">读此印文</button><button :aria-pressed="lens==='related'" @click="lens='related'">以字寻印 <b>{{related.length}}</b></button><span v-if="letter">正在沿「{{selectedChar?.label}}」找印 <button @click="clearLetter" aria-label="清除汉字线索"><IconX :size="12"/></button></span></div><div class="seal-space"><NeuralGraphCanvas v-if="view==='space'&&context" :data="context" :selected="selected" :center="anchor" :depth="0" exhibit @select="inspect" @fallback="view='study'" @preview-error="markFailed"/><SealStudyChart v-else-if="context" :data="context" :anchor="anchor" :selected="selected" @select="inspect"/></div><footer class="seal-stage-caption"><span><b>{{context?.nodes.filter(n=>n.kind==='seal_object').length}}</b> 条馆藏记录 · <b>{{context?.edges.length}}</b> 条释文关系</span><span>点击印章换主角 · 点击汉字追线索</span></footer><p class="seal-space-note">图中是官方馆藏图像的空间展签，不是文物三维复原。关联展签最多显示8条；共用汉字表示文字关联，不推断同一作者、风格或年代。</p></section>
  <aside class="seal-desk"><div class="seal-section-title"><span>03</span><h2>读印与查证</h2><button aria-label="放大当前印稿" @click="expanded=true"><IconMaximize :size="15"/></button></div><div class="seal-print-plate"><button @click="expanded=true" aria-label="打开当前印稿大图"><img v-if="preview" :src="preview.display_url" :alt="current.label+'官方馆藏图像'" @error="markFailed(current.id)"><span v-else>当前条目暂无原图预览</span><small><IconMaximize :size="13"/>放大细看</small></button><div><span>释文</span><h3>{{current.label}}</h3><p>{{fields.script}}<br>{{official?.period}} · {{official?.material}}</p></div></div><dl v-if="official" class="seal-official-facts"><dt>官方定名</dt><dd>{{official.official_title}}</dd><dt>馆藏机构</dt><dd>{{official.museum}}</dd><dt>{{official.accession_number?'文物号':'官方条目号'}}</dt><dd>{{official.accession_number||official.catalogue_record_id+'（非文物号）'}}</dd><dt>尺寸</dt><dd>{{official.dimensions}}</dd><dt>核对范围</dt><dd>官方馆藏记录；不等同系统独立鉴定</dd></dl><section v-if="official?.period_conflict" class="seal-source-difference"><b>来源分期不同，保留待核对</b><p>目录：{{official.period_index}}<br>正文：{{official.period_body}}</p></section><p v-if="official?.maker" class="seal-maker">目录制印人：{{official.maker}}<a v-if="official.field_provenance?.period_and_maker" :href="official.field_provenance.period_and_maker.index_url" target="_blank" rel="noopener noreferrer">核对目录 ↗</a></p><section v-if="official?.source_excerpt" class="seal-official-excerpt"><h4>官方简介节录</h4><blockquote>{{official.source_excerpt}}{{official.source_excerpt_truncated?'…':''}}</blockquote><a :href="official.page_url" target="_blank" rel="noopener noreferrer">阅读完整原文 ↗</a><p v-if="official.caption_note">{{official.caption_note}}</p><p v-if="official.interpretation_note">{{official.interpretation_note}}</p></section><figure v-if="official?.impression" class="seal-official-impression"><img :src="official.impression.display_url" :alt="official.impression.caption"><figcaption>官方钤本 · {{official.transcription_scope}}</figcaption></figure><div class="seal-read-chars"><span>沿一个字，找到另一方印</span><div><button v-for="r in characters" :key="r.node.id" :aria-label="'沿汉字'+r.node.label+'寻找印稿'" :aria-pressed="letter===r.node.id" @click="chooseLetter(r.node)">{{r.node.label}}</button></div><small>上方为网页释文顺序；不据此推定印面排布。</small></div>
   <section v-if="selectedType==='edge'&&selectedEdge" class="seal-evidence-mini"><h3>这条关系的依据</h3><p>{{edgeNames}}</p><span>{{selectedEdge.label}} · {{selectedEdge.assertion_source==='page_fetched'?'页面提取':'手工引用'}} · {{data.statuses[selectedEdge.status]}}</span><button @click="emit('workbench',selectedEdge.id,'edge')">查看读取凭证与核验记录 ↗</button><a v-for="d in claimDocuments" :key="d.id" :href="d.url" target="_blank" rel="noopener noreferrer">{{d.title}} · 关系证据 ↗</a></section>
   <section v-if="compare&&compared&&comparison" class="seal-comparison"><header><h3><IconGitCompare :size="14"/>两印对读</h3><button aria-label="关闭两印对读" @click="compare=''"><IconX :size="14"/></button></header><div class="seal-compare-images"><figure><img v-if="preview" :src="preview.display_url" :alt="current.label" @error="markFailed(current.id)"><figcaption>{{current.label}}</figcaption></figure><figure><img v-if="previewFor(compared,registry)" :src="previewFor(compared,registry)!.display_url" :alt="compared.label" @error="markFailed(compared.id)"><figcaption>{{compared.label}}</figcaption></figure></div><p>共用释文：<b>{{comparison.shared.map(n=>n.label).join('、')||'无'}}</b></p><small>并排观察字形与章法；共享文字不等同于同一风格。</small></section>
   <section class="seal-related"><header><h3>{{letter?'含「'+selectedChar?.label+'」的其他印章':'与此印共用文字'}}</h3><small>{{related.length}} 条</small></header><div class="seal-related-list"><article v-for="r in related.slice(0,4)" :key="r.node.id"><button @click="selectSeal(r.node)"><img v-if="previewFor(r.node,registry)" :src="previewFor(r.node,registry)!.display_url" :alt="r.node.label" @error="markFailed(r.node.id)"><span><b>{{r.node.label}}</b><small>共字：{{r.shared.map(x=>x.node.label).join('、')}}</small></span></button><button :aria-label="'与'+r.node.label+'对读'" :aria-pressed="compare===r.node.id" @click="addCompare(r.node)"><IconArrowsExchange :size="15"/></button></article><p v-if="!related.length">当前资料中未找到共字印章。</p><RouterLink v-if="selectedChar" :to="'/catalog?character='+encodeURIComponent(selectedChar.label)">检索所有含此字的馆藏记录 ↗</RouterLink></div></section>
   <section class="seal-source"><div><span>出处</span><a v-if="provenance" :href="provenance.url" target="_blank" rel="noopener noreferrer">{{provenance.title}} · 原始页面 ↗</a></div><small>{{reviewSummary}}。年代、材质及尺寸引用官方条目；具名制印人仅按官方目录列示。</small><details v-if="anchorDocuments.length>1"><summary>此印的 {{anchorDocuments.length}} 份资料</summary><a v-for="d in anchorDocuments" :key="d.id" :href="d.url" target="_blank" rel="noopener noreferrer">{{d.title}} ↗</a></details><button @click="emit('workbench',anchor,'node')">查看完整资料与读取凭证<IconArrowUpRight :size="13"/></button></section>
  </aside>
 </div>
 <section v-else-if="data&&!loading" class="seal-loading"><h2>当前筛选没有可核对的馆藏印章</h2><p>候选或已排除关系不作为释文依据。</p><button @click="emit('full')">查看全部馆藏记录 ↗</button></section>
 <section v-if="data" class="seal-understory"><div><span class="seal-eyebrow">资料中的文字线索</span><h2>哪些字，让馆藏印章相连？</h2><p>统计当前选定资料集中，包含该字的不同馆藏印章数量。点击一个字继续探索。</p></div><SealStudyChart :data="readingData!" :selected="letter" frequency @select="(id)=>{const n=data?.nodes.find(n=>n.id===id);if(n)chooseLetter(n)}"/><a href="https://github.com/Gezelli-z/moshi" target="_blank" rel="noopener noreferrer">平面交互参考「墨识」<IconArrowUpRight :size="14"/></a></section>
 <footer class="seal-page-footer"><span>馆藏图像与钤本来自对应博物馆官方藏品页，供本机研读；缺项不编造。</span><button @click="emit('workbench',anchor||undefined,'node')">打开全部资料与关系 ↗</button></footer>
 <div v-if="expanded" class="seal-lightbox-backdrop" @click.self="expanded=false"><section ref="modal" class="seal-lightbox" role="dialog" aria-modal="true" :aria-label="current?.label+'原始印稿预览'" tabindex="-1"><header><div><span class="seal-eyebrow">官方馆藏图像</span><h2>{{current?.label}}</h2></div><button aria-label="关闭印稿大图" @click="expanded=false"><IconX :size="21"/></button></header><div class="seal-large-image"><img v-if="preview" :src="preview.display_url" :alt="current?.label" @error="markFailed(current?.id)" :style="{width:300*zoom+'px',height:'auto',transform:`scaleX(${mirror?-1:1})`}"></div><footer><label>放大<input type="range" min="1" max="3" step=".1" v-model.number="zoom" aria-label="印稿查看倍率"><span>{{zoom.toFixed(1)}}×</span></label><button :aria-pressed="mirror" @click="mirror=!mirror">镜像查看</button><a :href="sourceDoc?.url" target="_blank" rel="noopener noreferrer">打开出处 ↗</a></footer><p>使用原站现有分辨率；镜像只改变查看方向，不修改原图或释文。</p></section></div>
</main>
</template>
